import sys

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    exact = [[0] * n for _ in range(n)]
    p = 2
    for _ in range(m):
        l = data[p] - 1
        r = data[p + 1] - 1
        x = data[p + 2] - 1
        p += 3
        exact[l][r] |= 1 << x

    choose = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        choose[i][0] = choose[i][i] = 1
        for j in range(1, i):
            choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD

    forbidden = [[0] * n for _ in range(n)]
    dp = [[0] * n for _ in range(n)]
    for length in range(1, n + 1):
        for l in range(n - length + 1):
            r = l + length - 1
            if length == 1:
                mask = exact[l][r]
            else:
                mask = forbidden[l + 1][r] | forbidden[l][r - 1] | exact[l][r]
            forbidden[l][r] = mask
            total = 0
            for k in range(l, r + 1):
                if not ((mask >> k) & 1):
                    left = 1 if k == l else dp[l][k - 1]
                    right = 1 if k == r else dp[k + 1][r]
                    total = (total + choose[length - 1][k - l] * left * right) % MOD
            dp[l][r] = total
    print(dp[0][n - 1])

if __name__ == '__main__':
    solve()

