import sys

def main():
    rd = sys.stdin.buffer.readline
    n, m, q = map(int, rd().split())
    edges = []
    for _ in range(m):
        a, b, c = map(int, rd().split())
        edges.append((a - 1, b - 1, c))

    queries = []
    closed = [False] * m
    for _ in range(q):
        z = list(map(int, rd().split()))
        if z[0] == 1:
            e = z[1] - 1
            queries.append((1, e))
            closed[e] = True
        else:
            queries.append((2, z[1] - 1, z[2] - 1))

    INF = 10 ** 30
    d = [[INF] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for i, (a, b, c) in enumerate(edges):
        if not closed[i]:
            d[a][b] = c
            d[b][a] = c

    # All roads which are present at the end are now present.  Floyd-Warshall.
    for k in range(n):
        dk = d[k]
        for i in range(n):
            di = d[i]
            x = di[k]
            if x != INF:
                for j in range(n):
                    y = x + dk[j]
                    if y < di[j]:
                        di[j] = y

    out = []
    for z in reversed(queries):
        if z[0] == 2:
            x = d[z[1]][z[2]]
            out.append(str(x if x < INF else -1))
        else:
            u, v, w = edges[z[1]]
            # Keep endpoint rows from before inserting this edge.
            du = d[u][:]
            dv = d[v][:]
            for i in range(n):
                di = d[i]
                iu = du[i]
                iv = dv[i]
                for j in range(n):
                    x = iu + w + dv[j]
                    if x < di[j]:
                        di[j] = x
                    x = iv + w + du[j]
                    if x < di[j]:
                        di[j] = x

    sys.stdout.write('\n'.join(reversed(out)))

if __name__ == '__main__':
    main()

