import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    processes = [tuple(data[2 + 4*i:6 + 4*i]) for i in range(n)]

    def feasible(w):
        total = 0
        for a, p, b, q in processes:
            cost = 10**30
            for s in range(b):
                rem = w - a*s
                t = 0 if rem <= 0 else (rem + b - 1)//b
                cost = min(cost, s*p + t*q)
            for t in range(a):
                rem = w - b*t
                s = 0 if rem <= 0 else (rem + a - 1)//a
                cost = min(cost, s*p + t*q)
            total += cost
