class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        # dp[k] is the number of stage assignments using exactly k stages.
        dp = [0] * (n + 1)
        dp[0] = 1
        for i in range(n):
            nxt = [0] * (n + 1)
            for k in range(i + 2):
                if k <= i:
                    nxt[k] = (nxt[k] + dp[k] * k) % MOD
                if k > 0:
                    # The new performer starts one of the x-(k-1) unused stages.
                    nxt[k] = (nxt[k] + dp[k - 1] * (x - k + 1)) % MOD
            dp = nxt

        ans = 0
        score_power = 1
        for k in range(1, n + 1):
            score_power = score_power * y % MOD
            ans = (ans + dp[k] * score_power) % MOD
        return ans

