class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Binomial coefficients for choosing the remaining set bits.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # A number with j set bits is reducible precisely when j reaches
        # one within at most k-1 further applications.
        good = [False] * (n + 1)
        for j in range(1, n + 1):
            x = j
            steps = 0
            while x > 1:
                x = x.bit_count()
                steps += 1
            good[j] = steps <= k - 1

        # Digit-DP: at each 1 in s, make this bit zero, then choose the
        # required number of ones freely in the suffix.
        answer = 0
        used = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for total in range(1, n + 1):
                    need = total - used
                    if good[total] and 0 <= need <= remaining:
                        answer = (answer + comb[remaining][need]) % MOD
                used += 1
        return answer

