    if Q > 0:
        add(start - 1)
    if Q + 1 < W:
        add(start + 1)

    while frontier and frontier[0][0] * X < strength:
        value, cell = heapq.heappop(frontier)
        strength += value
        row, col = divmod(cell, W)
        if row > 0:
            add(cell - W)
        if row + 1 < H:
            add(cell + W)
        if col > 0:
            add(cell - 1)
        if col + 1 < W:
            add(cell + 1)

    print(strength)


