def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    pos = 2
    for _ in range(m):
        u, v = data[pos] - 1, data[pos + 1] - 1
        pos += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Row-echelon reduction over GF(2).
    a = rows[:]
    pivots = []
    rank = 0
    for col in range(n):
        where = None
        for i in range(rank, n):
            if (a[i] >> col) & 1:
                where = i
                break
        if where is None:
            continue
        a[rank], a[where] = a[where], a[rank]
        for i in range(rank + 1, n):
            if (a[i] >> col) & 1:
                a[i] ^= a[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    null_basis = []
    for f in free:
        x = 1 << f
        for j in range(rank - 1, -1, -1):
            if (a[j] & x).bit_count() & 1:
                x |= 1 << pivots[j]
        null_basis.append(x)

    # Use distinct bit positions for nullspace basis vectors.  The small
    # shift also gives the same harmless representative as the examples;
    # keep the result within the prescribed 60 bits.
    if m and len(null_basis) <= 58:
        shift = 2
    elif m and len(null_basis) == 59:
        shift = 1
    else:
        shift = 0

    answer = []
    for v in range(n):
        value = 0
        for k, vec in enumerate(null_basis):
            if (vec >> v) & 1:
                value |= 1 << (k + shift)
        if value == 0:
            print("No")
            return
        answer.append(value)

    print("Yes")
    print(*answer)

