class Solution:
    def lenOfVDiagonal(self, grid):
        n = len(grid)
        m = len(grid[0])
        total = n * m
        directions = ((1, 1), (1, -1), (-1, -1), (-1, 1))

        straight = [[array('H', [0]) * total for _ in range(2)] for _ in range(4)]
        turning = [[array('H', [0]) * total for _ in range(2)] for _ in range(4)]

        # straight[d][p][cell]: length starting at cell, whose required
        # value is 2 (p=0) or 0 (p=1), without turning.
        for d, (dr, dc) in enumerate(directions):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    idx = r * m + c
                    nr, nc = r + dr, c + dc
                    for p in (0, 1):
                        if grid[r][c] == (2 if p == 0 else 0):
                            straight[d][p][idx] = 1
                            if 0 <= nr < n and 0 <= nc < m:
                                straight[d][p][idx] += straight[d][1 - p][nr * m + nc]

        # Clockwise order in matrix coordinates is SE, SW, NW, NE.
        for d, (dr, dc) in enumerate(directions):
            tr, tc = directions[(d + 1) % 4]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    idx = r * m + c
                    for p in (0, 1):
                        if grid[r][c] != (2 if p == 0 else 0):
                            continue
                        best = 0
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            best = turning[d][1 - p][nr * m + nc]
                        nr, nc = r + tr, c + tc
                        if 0 <= nr < n and 0 <= nc < m:
                            best = max(best, straight[(d + 1) % 4][1 - p][nr * m + nc])
                        turning[d][p][idx] = 1 + best

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                answer = max(answer, 1)
                for d, (dr, dc) in enumerate(directions):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        answer = max(answer, 1 + turning[d][0][nr * m + nc])
        return answer

