from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def count(odds, evens, first_parity):
            if odds + evens == 0:
                return 1
            if first_parity == 1:
                if odds != evens and odds != evens + 1:
                    return 0
            else:
                if evens != odds and evens != odds + 1:
                    return 0
            return fact[odds] * fact[evens]

        odds = (n + 1) // 2
        evens = n // 2
        total = count(odds, evens, 1) + count(odds, evens, 0)
        if k > total:
            return []

        remaining = set(range(1, n + 1))
        answer = []
        previous_parity = -1

        while remaining:
            for value in sorted(remaining):
                parity = value & 1
                if previous_parity != -1 and parity == previous_parity:
                    continue

                next_odds = odds - (parity == 1)
                next_evens = evens - (parity == 0)
                ways = count(next_odds, next_evens, 1 - parity)

                if k > ways:
                    k -= ways
                else:
                    answer.append(value)
                    remaining.remove(value)
                    odds, evens = next_odds, next_evens
                    previous_parity = parity
                    break

        return answer

