class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2
        weights = []
        for i in range(half):
            j = n - 1 - i
            w = pow(10, j, k)
            if i != j:
                w = (w + pow(10, i, k)) % k
            weights.append(w)

        possible = [[False] * k for _ in range(half + 1)]
        possible[half][0] = True
        for i in range(half - 1, -1, -1):
            w = weights[i]
            following = possible[i + 1]
            current = possible[i]
            start = 1 if i == 0 else 0
            for residue in range(k):
                for digit in range(start, 10):
                    if following[(residue - digit * w) % k]:
                        current[residue] = True
                        break

        digits = []
        residue = 0
        for i, w in enumerate(weights):
            start = 1 if i == 0 else 0
            for digit in range(9, start - 1, -1):
                if possible[i + 1][(-residue - digit * w) % k]:
                    digits.append(str(digit))
                    residue = (residue + digit * w) % k
                    break

        left = ''.join(digits)
        if n % 2:
            return left + left[-2::-1]
        return left + left[::-1]

