from functools import cmp_to_key


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [(data[i], data[i + 1]) for i in range(2, 2 * n + 2, 2)]

    # Sort in the order outer-to-inner in an optimal composition.
    # The relevant key is B/(A-1), with A=1 treated as infinity.
    def compare(x, y):
        a, b = x
        c, d = y
        if a == 1:
            return 0 if c == 1 else 1
        if c == 1:
            return -1
        cross = b * (c - 1) - d * (a - 1)
        if cross < 0:
            return -1
        if cross > 0:
            return 1
        return 0

    funcs.sort(key=cmp_to_key(compare))

    # Process from inner to outer. dp[j] is the best value after choosing j.
    dp = [-1] * (k + 1)
    dp[0] = 1
    for a, b in reversed(funcs):
        for j in range(k, 0, -1):
            if dp[j - 1] != -1:
                candidate = a * dp[j - 1] + b
                if candidate > dp[j]:
                    dp[j] = candidate

    print(dp[k])


