class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1

        n = len(s)
        answer = n
        for target in range(1, n + 1):
            # State 0: this letter is absent in the final string.
            # State 1: it occurs target times.
            dp = [counts[0], abs(counts[0] - target)]
            for i in range(1, 26):
                nxt = [10**18, 10**18]
                for previous in (0, 1):
                    supply = (counts[i - 1] if previous == 0
                              else max(counts[i - 1] - target, 0))
                    for current in (0, 1):
                        own = (counts[i] if current == 0
                               else abs(counts[i] - target))
                        deficit = (max(target - counts[i], 0)
                                   if current else 0)
                        # Moving an available character right saves one
                        # operation compared with delete plus insertion.
                        cost = dp[previous] + own - min(supply, deficit)
                        if cost < nxt[current]:
                            nxt[current] = cost
                dp = nxt
            answer = min(answer, dp[0], dp[1])
        return answer

