import sys
MOD = 998244353

class DSU:
    def __init__(self, n):
        self.p = list(range(n))
        self.x = [0] * n
    def find(self, a):
        if self.p[a] != a:
            q = self.p[a]
            self.p[a] = self.find(q)
            self.x[a] ^= self.x[q]
        return self.p[a]
    def add(self, a, b, v):
        ra = self.find(a)
        xa = self.x[a]
        rb = self.find(b)
        xb = self.x[b]
        if ra == rb:
            return (xa ^ xb) == v
        self.p[ra] = rb
        self.x[ra] = xa ^ xb ^ v
        return True

def solve(H, W, S):
    dsu = DSU(W)
    vertical = [0] * W
    free_rows = 0
    for row in S:
        cnt_a = row.count('A')
        if cnt_a & 1:
            return 0
        for j, c in enumerate(row):
            if c == 'A':
                vertical[j] ^= 1
        if cnt_a == W:
            free_rows += 1
            continue
        pref = [0] * W
        cur = 0
        for j, c in enumerate(row):
            pref[j] = cur
            if c == 'A':
                cur ^= 1
        bpos = [j for j, c in enumerate(row) if c == 'B']
        k = bpos[0]
        for j in bpos[1:]:
            relation = pref[j] ^ pref[k] ^ vertical[j] ^ vertical[k]
            if not dsu.add(j, k, relation):
                return 0
        for j, c in enumerate(row):
            if c == 'A':
                vertical[j] ^= 1
    if any(vertical):
        return 0
    components = sum(dsu.find(i) == i for i in range(W))
    return pow(2, components + free_rows, MOD)

def main():
    data = iter(sys.stdin.buffer.read().split())
    t = int(next(data))
    ans = []
    for _ in range(t):
        h = int(next(data)); w = int(next(data))
        s = [next(data).decode() for _ in range(h)]
        ans.append(str(solve(h, w, s)))
    sys.stdout.write('\n'.join(ans))

main()

