class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        first, middle, last = p.split('*')

        def occurrences(word):
            if not word:
                return list(range(n + 1))
            m = len(word)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and word[i] != word[j]:
                    j = pi[j - 1]
                if word[i] == word[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != word[j]:
                    j = pi[j - 1]
                if ch == word[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        starts_first = occurrences(first)
        starts_middle = occurrences(middle)
        starts_last = occurrences(last)
        if not starts_first or not starts_middle or not starts_last:
            return -1

        # For each middle occurrence, find the latest compatible first start.
        best_at_middle = [-1] * (n + 1)
        first_index = 0
        latest = -1
        first_length = len(first)
        for middle_start in starts_middle:
            limit = middle_start - first_length
            while (first_index < len(starts_first) and
                   starts_first[first_index] <= limit):
                latest = starts_first[first_index]
                first_index += 1
            if latest >= 0:
                best_at_middle[middle_start] = latest

        # Prefix maxima permit any middle occurrence ending before last starts.
        running = -1
        for i in range(n + 1):
            if best_at_middle[i] > running:
                running = best_at_middle[i]
            best_at_middle[i] = running

        middle_length = len(middle)
        last_length = len(last)
        answer = n + 1
        for last_start in starts_last:
            limit = last_start - middle_length
            if limit >= 0:
                start = best_at_middle[limit]
                if start >= 0:
                    answer = min(answer, last_start + last_length - start)

        return -1 if answer == n + 1 else answer

