import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    seen = [False] * n
    rel = [0] * n
    ans = [0] * n

    for start in range(n):
        if seen[start]:
            continue
        seen[start] = True
        rel[start] = 0
        stack = [start]
        nodes = []
        while stack:
            u = stack.pop()
            nodes.append(u)
            for v, z in adj[u]:
                expected = rel[u] ^ z
                if not seen[v]:
                    seen[v] = True
                    rel[v] = expected
                    stack.append(v)
                elif rel[v] != expected:
                    print(-1)
                    return

        counts = [0] * 30
        for u in nodes:
            x = rel[u]
            for b in range(30):
                counts[b] += (x >> b) & 1
        shift = 0
        size = len(nodes)
        for b, count in enumerate(counts):
            if count * 2 > size:
                shift |= 1 << b
        for u in nodes:
            ans[u] = rel[u] ^ shift

    print(*ans)

if __name__ == '__main__':
    main()

