import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    a = data[2:]

    total = 0
    for v in a:
        total ^= v

    r = min(k, n - k)
    if r == 0:
        print(total)
        return

    complement = k > n // 2
    best = 0

    def dfs(start, left, value):
        nonlocal best
        if left == 0:
            candidate = total ^ value if complement else value
            if candidate > best:
                best = candidate
            return
        end = n - left + 1
        for i in range(start, end):
            dfs(i + 1, left - 1, value ^ a[i])

    dfs(0, r, 0)
    print(best)

if __name__ == "__main__":
    solve()

