from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)
        for a in children:
            a.sort()

        stack = [(0, 0)]
        order = []
        while stack:
            v, state = stack.pop()
            if state == 0:
                stack.append((v, 1))
                for u in reversed(children[v]):
                    stack.append((u, 0))
            else:
                order.append(v)

        pos = [0] * n
        for i, v in enumerate(order):
            pos[v] = i
        size = [1] * n
        for v in order:
            if parent[v] >= 0:
