            for w in g[v]:
                if d[w]<0: d[w]=d[v]+1; q.append(w)
        return d
    ds=bfs(s); dt=bfs(t); D=ds[t]
    # Bipartite graphs cannot realize an odd transposition of two tokens.
    col=[-1]*n; bip=True
    for z in range(n):
        if col[z]>=0: continue
        col[z]=0; q=deque([z])
        while q:
            v=q.popleft()
            for w in g[v]:
                if col[w]<0: col[w]=col[v]^1; q.append(w)
                elif col[w]==col[v]: bip=False
    if bip:
        print(-1); return
    # Check whether two internally vertex-disjoint shortest paths exist.
    # A compact augmenting-path flow, with vertex capacities one.
    adj=[[] for _ in range(n)]
    for v in range(n):
        if ds[v]<0: continue
        for w in g[v]:
            if ds[w]==ds[v]+1 and ds[v]+1+dt[w]==D:
                adj[v].append(w)
