class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        M = [0] * (4 * n)
        B = [0] * (4 * n)
        H = [0] * (4 * n)

        def value(m, b, x):
            return m * x + b

        def add(node, left, right, m, b):
            if not H[node]:
                H[node] = 1
                M[node] = m
                B[node] = b
                return
            mid = (left + right) // 2
            if value(m, b, mid) > value(M[node], B[node], mid):
                M[node], m = m, M[node]
                B[node], b = b, B[node]
            if left == right:
                return
            if value(m, b, left) > value(M[node], B[node], left):
                add(node * 2, left, mid, m, b)
            elif value(m, b, right) > value(M[node], B[node], right):
                add(node * 2 + 1, mid + 1, right, m, b)

        def query(node, left, right, x):
            if not H[node]:
                return -10**30
            ans = value(M[node], B[node], x)
            if left == right:
                return ans
            mid = (left + right) // 2
            if x <= mid:
                return max(ans, query(node * 2, left, mid, x))
            return max(ans, query(node * 2 + 1, mid + 1, right, x))

        add(1, 0, n - 1, nums[0], 0)
        score = 0
        for j in range(1, n):
            score = query(1, 0, n - 1, j)
            add(1, 0, n - 1, nums[j], score - j * nums[j])
        return score

