class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        if all(x == 0 for x in nums):
            return 0

        limit = max(nums)
        mask = (1 << (limit + 1)) - 1
        # dp[i]'s bit s is set iff s can be formed at index i
        # using the processed queries that cover i.
        dp = [1] * n

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                dp[i] |= dp[i] << value
                dp[i] &= mask

            if all((dp[i] >> nums[i]) & 1 for i in range(n)):
                return k
        return -1

