import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        lo = 10 ** (digits - 1)
        hi = 10 ** digits

        prime = [True] * hi
        prime[0] = prime[1] = False
        p = 2
        while p * p < hi:
            if prime[p]:
                prime[p * p:hi:p] = [False] * (((hi - 1 - p * p) // p) + 1)
            p += 1

        if prime[n] or prime[m]:
            return -1
        if n == m:
            return n

        inf = 10 ** 30
        dist = [inf] * hi
        dist[n] = n
        heap = [(n, n)]
        powers = [10 ** i for i in range(digits)]

        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            for power in powers:
                digit = (x // power) % 10
                if digit < 9:
                    y = x + power
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(heap, (cost + y, y))
                if digit > 0:
                    y = x - power
                    if y >= lo and not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(heap, (cost + y, y))

        return -1

