from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # Z-function: z[i] is the common-prefix length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        answer = 0

        # First condition: nums[0:i] is a prefix of nums[i:j].
        for i in range(1, n):
            if z[i] >= i:
                first_j = max(i + 1, 2 * i)
                if first_j < n:
                    answer += n - first_j

        # Second condition.  Put d = j-i.  For each fixed d, scan its
        # diagonal backwards to obtain the matching run length.
        for d in range(1, n):
            matching = 0
            for i in range(n - d - 1, -1, -1):
                if nums[i] == nums[i + d]:
                    matching += 1
                else:
                    matching = 0
                if i + 2 * d <= n and matching >= d:
                    answer += 1
                    # This split was already counted by the first condition.
                    if d >= i and z[i] >= i:
                        answer -= 1

        return answer

