from collections import deque

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        reverse = [[] for _ in range(n)]
        weights = set()
        for a, b, w in edges:
            reverse[b].append((a, w))
            weights.add(w)

        levels = sorted(weights)

        def reachable(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            queue = deque([0])
            reached = 1
            while queue:
                v = queue.popleft()
                for u, w in reverse[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = True
                        reached += 1
                        if reached == n:
                            return True
                        queue.append(u)
            return reached == n

        if not levels or not reachable(levels[-1]):
            return -1

        left, right = 0, len(levels) - 1
        while left < right:
            mid = (left + right) // 2
            if reachable(levels[mid]):
                right = mid
            else:
                left = mid + 1
        return levels[left]

