class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        total = s.count('1')
        best = 0
        n = len(s)
        i = 0
        while i < n:
            if s[i] != '1':
                i += 1
                continue

            start = i
            while i < n and s[i] == '1':
                i += 1
            end = i

            # This one-run can be removed only if it has zeroes on both sides.
            if start > 0 and end < n and s[start - 1] == '0' and s[end] == '0':
                left = start - 1
                while left >= 0 and s[left] == '0':
                    left -= 1
                right = end
                while right < n and s[right] == '0':
                    right += 1
                gain = (start - 1 - left) + (right - end)
                if gain > best:
                    best = gain

        return total + best

