class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        def at_most(K):
            if K < 0:
                return 0
            left = 0
            cons = 0
            last = {c: -1 for c in 'aeiou'}
            ans = 0
            for right, ch in enumerate(word):
                if ch in last:
                    last[ch] = right
                else:
                    cons += 1
                while cons > K:
                    if word[left] not in last:
                        cons -= 1
                    left += 1
                m = min(last.values())
                if m >= left:
                    ans += m - left + 1
            return ans
        return at_most(k) - at_most(k - 1)

